content.query:
let TotalRequests=toscalar(AGWAccessLogs
| where TimeGenerated {TimeRange}
| where _ResourceId in~ ({AppGateways})
| count);
let BlockedRaw=toscalar(AGWFirewallLogs
| where TimeGenerated {TimeRange}
| where _ResourceId in~ ({AppGateways})
| where tolower(Action) in ("blocked", "detected and blocked", "jschallengeblock")
| summarize dcount(TransactionId));
let Blocked=min_of(TotalRequests, BlockedRaw);
let Passed=max_of(TotalRequests - Blocked, 0);
let BlockRate=iff(TotalRequests == 0, 0.0, round(100.0 * Blocked / TotalRequests, 2));
union
(print Disposition=strcat("Blocked (", BlockRate, "%)"), Requests=Blocked),
(print Disposition="Not blocked", Requests=Passed)
